def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = sorted({v for row in grid for v in row if v != 0})
    objs = []

    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(w)
                 if grid[r][c] == color]
        minr = min(r for r, c in cells)
        maxr = max(r for r, c in cells)
        minc = min(c for r, c in cells)
        maxc = max(c for r, c in cells)
        crop = [[grid[minr + r][minc + c]
                 for c in range(maxc - minc + 1)]
                for r in range(maxr - minr + 1)]
        objs.append((minr, minc, crop))

    if not objs:
        return []

    rows = [o[0] for o in objs]
    cols = [o[1] for o in objs]
    horizontal = (max(cols) - min(cols)) >= (max(rows) - min(rows))

    if horizontal:
        objs.sort(key=lambda o: o[1])
        out = [[0] * (3 * len(objs)) for _ in range(3)]
        for i, (_, _, crop) in enumerate(objs):
            for r in range(len(crop)):
                for c in range(len(crop[0])):
                    out[r][3 * i + c] = crop[r][c]
    else:
        objs.sort(key=lambda o: o[0])
        out = [[0] * 3 for _ in range(3 * len(objs))]
        for i, (_, _, crop) in enumerate(objs):
            for r in range(len(crop)):
                for c in range(len(crop[0])):
                    out[3 * i + r][c] = crop[r][c]

    return out
